"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-2169-01-01:0":{"b": ["Akhir Troya II / Troya III (Zaman Perunggu Awal): fase Troya III berakhir", "1237db63"], "d": ["14C-AMS tulang hewan dari penggalian Cincinnati (26 sampel), dimodelkan dengan IntCal20: peralihan Troya II/III 2267±10, akhir Troya III 2170±10 cal SM.", "b3af61be"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-2266-01-01:0":{"b": ["Akhir Troya II / Troya III (Zaman Perunggu Awal): fase Troya III dimulai", "0e6da4ee"], "d": ["14C-AMS tulang hewan dari penggalian Cincinnati (26 sampel), dimodelkan dengan IntCal20: peralihan Troya II/III 2267±10, akhir Troya III 2170±10 cal SM.", "b3af61be"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-2919-01-01:0":{"b": ["Troya I (Hisarlık, awal Zaman Perunggu Awal): fase Troya Ia dimulai (Weninger 1995)", "2d436c8d"], "d": ["Tanggal untuk awal fase Troya Ia (fondasi batu apsidal) yang diturunkan dari 14C terkalibrasi dendro; Troya I total 9 fase arsitektur (Ia-Ii), dengan asumsi panjang rata-rata fase 50 tahun.", "2f40873c"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-9149-01-01:0":{"b": ["Klimonas dan Shillourokambos (Siprus, Neolitikum Aseramik Awal): desa menetap pertama di Siprus (Klimonas)", "7f9f9d76"], "d": ["Penduduk desa yang menetap di Klimonas hidup 11.100-10.600 tahun lalu (probabilitas tertinggi 10.8-10.6 cal kyBP). Shillourokambos Awal A 10.4-10.0, Awal B-C 10.0-9.6, Tengah A ~9.5 cal kyBP (keterangan Gbr. 3, perbandingan).", "c01f6b39"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0183-01-01:0":{"b": ["Kekaisaran Maurya: dinasti Maurya berakhir", "1b4bed2f"], "d": ["Chandragupta (c. 321-297 SM), Bindusara (25/27/28 tahun), Ashoka; dinasti berakhir dengan jumlah Purana 137 tahun pada c. 184 SM dengan dibunuhnya Brihadratha oleh Pushyamitra (periode Shunga).", "5c9e3720"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0201-01-01:0":{"b": ["Pendirian dinasti Han - Liu Bang menyatakan diri kaisar (202 SM): dinasti Han Barat didirikan", "b6d66651"], "d": ["Setelah perang Chu-Han, Liu Bang mengambil gelar kaisar pada tahun ke-5 Han; periode Han Barat dihitung mulai 202.", "c15c87db"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0236-01-01:0":{"b": ["Pemerintahan Ashoka dan sinkronisme Dekret Batu XIII: Ashoka wafat", "39f8eb23"], "d": ["Pemerintahan Ashoka: menurut CHI 1922 aksesi ≤274, penobatan ≤270, penaklukan Kalinga ≤262, wafat 237/236 SM. Dekret Batu XIII menganggap lima raja Helenistik (Antiochos, Ptolemaios, Antigonos, Magas, Aleksandros) masih hidup; CHI, karena Magas wafat pada 258, menempatkan dekret itu 'sekitar 258-257 SM', secara sementara.", "62399b89"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0273-01-01:0":{"b": ["Pemerintahan Ashoka dan sinkronisme Dekret Batu XIII: Ashoka naik takhta", "7a0e6e1c"], "d": ["Pemerintahan Ashoka: menurut CHI 1922 aksesi ≤274, penobatan ≤270, penaklukan Kalinga ≤262, wafat 237/236 SM. Dekret Batu XIII menganggap lima raja Helenistik (Antiochos, Ptolemaios, Antigonos, Magas, Aleksandros) masih hidup; CHI, karena Magas wafat pada 258, menempatkan dekret itu 'sekitar 258-257 SM', secara sementara.", "62399b89"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0320-01-01:0":{"b": ["Kekaisaran Maurya: Kekaisaran Maurya: masa Chandragupta dimulai", "43e81ed7"], "d": ["Chandragupta (c. 321-297 SM), Bindusara (25/27/28 tahun), Ashoka; dinasti berakhir dengan jumlah Purana 137 tahun pada c. 184 SM dengan dibunuhnya Brihadratha oleh Pushyamitra (periode Shunga).", "5c9e3720"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0325-01-01:0":{"b": ["Dinasti Nanda (Magadha): Dhana-Nanda di Magadha (zaman Aleksandros)", "64e72b4d"], "d": ["Sembilan Nanda (Mahapadma dan delapan putranya) di Magadha; yang terakhir (Dhana Nanda) berada di takhta pada 326 SM; pada ~321 SM kedaulatan beralih ke Maurya. Tanggal pendirian tidak diberikan dalam sumber.", "c369d6b6"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0480-01-01:0":{"b": ["Awal catatan Chunqiu (Annal Musim Semi dan Gugur): periode Chunqiu berakhir", "aa4943a9"], "d": ["Annal Chunqiu negara Lu dimulai pada tahun ke-1 Adipati Yin (722) dan berakhir pada tahun ke-14 Adipati Ai (481); nama 'periode Musim Semi-Gugur' bersumber dari teks ini.", "9abe05ef"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0482-01-01:0":{"b": ["Tanggal parinirwana Buddha (dasar kronologi): parinirwana Buddha (tanggal Cambridge History)", "e4107ac0"], "d": ["CHI (1922) menempatkan wafatnya Buddha pada ~483 SM dengan menambahkan selang 218 tahun dalam kronik Ceylon sebelum Ashoka, dan menganggapnya 'sementara'.", "0b992e60"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0542-01-01:0":{"b": ["Kebangkitan Magadha (Bimbisara dan Ajatashatru): Bimbisara naik takhta Magadha", "42ca9a86"], "d": ["Cambridge History of India (1922), dengan kronologi Geiger yang berdasar kronik Sinhala, memberikan masa pemerintahan Bimbisara 543-491 dan Ajatashatru 491-459 SM; kebangkitan Magadha dimulai dengan penaklukan Anga (Bimbisara, c. 600 SM), dan keunggulan atas Kashi-Kosala-Videha dikaitkan dengan Ajatashatru.", "c1adf1d6"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0721-01-01:0":{"b": ["Awal catatan Chunqiu (Annal Musim Semi dan Gugur): periode Chunqiu dimulai", "a575d11c"], "d": ["Annal Chunqiu negara Lu dimulai pada tahun ke-1 Adipati Yin (722) dan berakhir pada tahun ke-14 Adipati Ai (481); nama 'periode Musim Semi-Gugur' bersumber dari teks ini.", "9abe05ef"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1045-01-01:0":{"b": ["Penaklukan Shang oleh Zhou (Muye) - pertentangan tanggal: Zhou mengalahkan Shang (1046; sumber menyebut 1045/1044/1040/1050)", "2fb1528d"], "d": ["Kemenangan Raja Wu atas Shang (Muye) dan pendirian dinasti Zhou; dalam literatur terbitan berpenilai sejawat, tanggalnya bertentangan antara 1050/1046/1045/1044/1040.", "3cee8749"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1299-01-01:0":{"b": ["Awal periode Mumun (padi/Zaman Perunggu) - perbandingan terkalibrasi: periode Mumun dimulai (Korea)", "8a36e4ef"], "d": ["Periode Mumun; pertanian padi + jewawut, perubahan menyeluruh dalam tata permukiman.", "4afd8b60"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1499-01-01:0":{"b": ["Dholavira: Fase VII Dholavira berakhir", "87ad0540"], "d": ["Kota Harappa di Kachchh (pulau Khadir); menurut skema UNESCO/ASI, permukiman sekitar 1.500 tahun dalam 7 fase yang dimulai c. 3000 SM; Fase VII (~1500-1450 SM) adalah permukiman terakhir yang tidak bersifat perkotaan, setelah itu tidak pernah dihuni lagi.", "a6493b11"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1499-01-01:1":{"b": ["Batas dinasti/periode Shang (kerangka Erligang-Yinxu): periode Shang dimulai (model 14C)", "98c7f77f"], "d": ["Dua nilai untuk awal Shang: ~1500 (Sci Rep 2018, Erligang Zhengzhou) dan ~1600 (Proyek Periodisasi; gelombang sebelumnya, Guangming Daily/Lee 2007). Akhir: penaklukan Zhou 1046 (Li 2002) dengan 14C ~1041.", "271aafb3"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1999-01-01:0":{"b": ["Lothal: kemunduran Lothal", "42da4755"], "d": ["Kota pelabuhan/produksi Harappa di pesisir Gujarat; menurut Rao, bangsa Harappa tiba di sini c. 2450 SM; tanggal TF terkalibrasi menempatkan fase Harappa Matang antara ~2650-2200 SM dan fase Harappa Akhir (B) antara ~2315-1865 SM.", "b1919748"]},
