"OLAYLAR_ARKEOLOJI_PILOT:-3299-01-01:0":{"b": ["Harappa: fase Ravi (Periode 1) dimulai — periode pra-lembah Indus", "61f95b02"], "d": ["Kronologi HARP memberi Periode 1 pada 3300–~2800 SM; tabel lain di situs yang sama memberi awal 3700 dan >3500.", "d5ccb125"]},
"OLAYLAR_ARKEOLOJI_PILOT:-4376-01-01:0":{"b": ["Mesir: budaya Badari dimulai (Lembah Nil, Mesir Hulu)", "96a2d769"], "d": ["Model Bayes menempatkan awal Badari antara 4489–4266 SM; ini adalah periode pra-negara Mesir.", "6b947b99"]},
"OLAYLAR_ARKEOLOJI_PILOT:-4383-01-01:0":{"b": ["Kegiatan pemakaman di nekropolis Varna berakhir", "d825a363"], "d": ["Pemakaman digunakan total ~120–260 tahun.", "75198dd6"]},
